/* @autogenerated */
package net.civeira.phylax.common.value.importation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Optional;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import net.civeira.phylax.common.value.validation.ConstraintFailList;

@DisplayName("EnumeratedLoad")
class EnumeratedLoadUnitTest {

  enum Sample {
    FIRST_VALUE, lower_value, Mixed
  }

  @ParameterizedTest(name = "\"{0}\" -> {1}")
  @CsvSource({"Mixed, Mixed", "first_value, FIRST_VALUE", "LOWER_VALUE, lower_value",
      "'Mixed ', Mixed", "'first value', FIRST_VALUE", "'LOWER VALUE', lower_value"})
  @DisplayName("Should resolve the constant through its text variants")
  void shouldResolveVariants(String value, Sample expected) {
    ConstraintFailList fails = new ConstraintFailList();
    assertEquals(Optional.of(expected),
        EnumeratedLoad.toEnumerated(Sample.class, "kind", value, fails));
    assertTrue(fails.isEmpty());
  }

  @ParameterizedTest(name = "\"{0}\"")
  @NullAndEmptySource
  @ValueSource(strings = {"  "})
  @DisplayName("Should report missing values as NOT_NULL")
  void shouldReportMissingValues(String value) {
    ConstraintFailList fails = new ConstraintFailList();
    assertTrue(EnumeratedLoad.toEnumerated(Sample.class, "kind", value, fails).isEmpty());
    assertTrue(fails.includeCode("NOT_NULL"));
  }

  @Test
  @DisplayName("Should report unknown constants as WRONG_VALUE")
  void shouldReportUnknownConstants() {
    ConstraintFailList fails = new ConstraintFailList();
    assertTrue(EnumeratedLoad.toEnumerated(Sample.class, "kind", "other", fails).isEmpty());
    assertTrue(fails.includeCode("WRONG_VALUE"));
  }

  @Test
  @DisplayName("Should report non enum types as WRONG_TYPE")
  @SuppressWarnings({"unchecked", "rawtypes"})
  void shouldReportNonEnumTypes() {
    ConstraintFailList fails = new ConstraintFailList();
    Class raw = Enum.class;
    assertTrue(EnumeratedLoad.toEnumerated(raw, "kind", "FIRST_VALUE", fails).isEmpty());
    assertTrue(fails.includeCode("WRONG_TYPE"));
  }
}
